    // Move lengthy storage guidance into a named disclosure, keeping the reminder limit visible.
    const storage=document.createElement('details');storage.className='eog-panel tracker-settings';storage.innerHTML=`<summary>${t('storageTitle')}</summary>`;
    const rememberLabel=section.querySelector('#med-remember').parentElement;const privacy=rememberLabel.nextElementSibling;const remindLabel=section.querySelector('#med-remind').parentElement;
    storage.append(rememberLabel,privacy,remindLabel);section.append(storage);section.querySelector('#med-remember').addEventListener('change',()=>queueMicrotask(trackerRows));
