    section.querySelector('#tracker-frequency').onchange=e=>{if(e.target.value!=='custom'){slots=Array.from({length:Number(e.target.value)},(_,i)=>slots[i]||'');drawTimes();}};
    section.querySelector('#tracker-add-time').onclick=()=>{if(slots.length>=24)return;slots.push('');section.querySelector('#tracker-frequency').value='custom';drawTimes();};
    section.querySelector('#tracker-time-inputs').oninput=e=>{if(e.target.matches('[data-time],[data-time-end]')){const i=Number(e.target.dataset.time??e.target.dataset.timeEnd),start=section.querySelector('[data-time="'+i+'"]').value,end=section.querySelector('[data-time-end="'+i+'"]').value;slots[i]=start+(end?'–'+end:'');syncTimes();}};
    section.querySelector('#tracker-time-inputs').onclick=e=>{const b=e.target.closest('[data-remove-time]');if(!b||slots.length===1)return;slots.splice(Number(b.dataset.removeTime),1);section.querySelector('#tracker-frequency').value='custom';drawTimes();};
    add.addEventListener('reset',()=>{slots=[''];drawTimes();});drawTimes();
    const remarks=document.createElement('div');remarks.id='tracker-remarks';remarks.className='eog-panel';remarks.innerHTML=`<h3>${t('remarks')}</h3><p class="eog-small">${t('byPatient')}</p><form id="tracker-remark-form"><label>${t('from')}<input type="date" name="date" value="${selectedDay}" required></label><label>${t('kind')}<select name="kind">${['noteType','concern','effect','improvement'].map(v=>`<option value="${v}">${t(v)}</option>`).join('')}</select></label><label>${t('remark')}<textarea name="text" maxlength="1000" required></textarea></label><button class="eog-button">${t('saveRemark')}</button></form><div id="tracker-remarks-list"></div>`;daily.after(remarks);
    remarks.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!validDay(String(f.get('date')))||String(f.get('date'))>day()||!String(f.get('text')).trim()){status(t('error'));return;}if(data.lockedDays?.[String(f.get('date'))]){status('This day is locked. Use Saved history → Add correction note.');return;}data.remarks=data.remarks||[];data.remarks.push({date:String(f.get('date')),kind:String(f.get('kind')),text:String(f.get('text')).trim(),recordedAt:new Date().toISOString()});if(persist())status(t('saved'));e.target.elements.text.value='';selectedDay=String(f.get('date'));section.querySelector('#med-day').value=selectedDay;renderRows();};
