  function trackerRows(){
    const panel=section.querySelector('#tracker-stats');if(!panel)return;
    storageStatus();
    const items=occurrences(selectedDay),counts={total:items.filter(o=>!o.s.asNeeded).length,takenLabel:0,missed:0,skipped:0,remaining:0};
    for(const o of items){const r=recordAt(o.id);if(o.s.asNeeded&&(!r||r.status==='unknown'))continue;counts[r?.status==='taken'?'takenLabel':r?.status==='missed'?'missed':r?.status==='skipped'?'skipped':'remaining']++;}
    panel.innerHTML=Object.entries(counts).map(([k,v])=>`<div><strong>${v}</strong><span>${t(k)}</span></div>`).join('');
    section.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===trackerView)));
    section.querySelector('#tracker-daily').hidden=trackerView==='list';
    section.querySelector('#med-doses').hidden=trackerView!=='daily';
    section.querySelector('#tracker-list').hidden=trackerView!=='list';
    section.querySelector('#tracker-week').hidden=trackerView!=='weekly';
    section.querySelector('#tracker-remarks').hidden=trackerView!=='daily';
    const start=new Date(selectedDay+'T12:00');start.setDate(start.getDate()-((start.getDay()+6)%7));
    section.querySelector('#tracker-week').innerHTML=`<h3>${t('weekly')}</h3><p class="eog-small">${t('weekHelp')}</p><div class="tracker-week-grid">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const date=day(d),items=occurrences(date);return `<button type="button" class="tracker-week-day" data-week-day="${date}" aria-pressed="${date===selectedDay}"><strong>${esc(d.toLocaleDateString(lang==='zh'?'zh-CN':lang,{weekday:'short',day:'numeric',month:'short'}))}</strong><span>${items.filter(o=>recordAt(o.id)?.status==='taken').length} / ${items.length} ${t('takenLabel')}</span>${items.slice(0,3).map(o=>`<small>${o.time} ${esc(o.s.name)} · ${describe(recordAt(o.id))}</small>`).join('')}${items.length>3?`<small>+${items.length-3} ${t('more')}</small>`:''}</button>`;}).join('')}</div>`;
    const remarks=archive.remarksFor(data,selectedDay);
    section.querySelector('#tracker-remark-form [name=date]').value=selectedDay;
    section.querySelector('#tracker-remarks-list').innerHTML=remarks.length?remarks.map(r=>`<article class="med-dose"><div><strong>${r.kind==='correction'?'Correction note':t(r.kind)}</strong><p>${esc(r.text)}</p><small>${esc(new Date(r.recordedAt).toLocaleString())}</small></div></article>`).join(''):`<p>${t('noRemarks')}</p>`;
    for(const [selector,list] of [['#med-doses article',items.map(o=>o.s)],['#med-schedules article',data.schedules]]){section.querySelectorAll(selector).forEach((el,i)=>{const s=list[i];el.style.borderLeft='4px solid '+(palette[s.colour]||palette.green);el.style.paddingLeft='16px';el.querySelector('[data-med-extra]')?.remove();if(s.medicineType||s.instructions){const extra=document.createElement('small');extra.dataset.medExtra='';extra.textContent=[s.medicineType?t(s.medicineType):'',s.instructions||''].filter(Boolean).join(' · ');el.firstElementChild.append(extra);}});}
    // Labels, not colours alone, identify status. Unrecorded never means missed.
    section.querySelectorAll('#med-doses article').forEach((el,i)=>{const o=items[i],r=recordAt(o.id);el.dataset.status=r?.status||'unknown';});
  }

