    controls.innerHTML='<button type="button" class="eog-button" id="plan-copy">Duplicate day / Repeat plan</button><button type="button" class="eog-button eog-secondary" id="plan-edit">Edit this day</button><p class="eog-small">Times run from morning through overnight. Repeat plan copies the medicines and times, not records of doses taken.</p>';
