    dialog.querySelector('#plan-rows').oninput=e=>{const row=e.target.closest('[data-plan-row]');if(!row)return;const s=draft[Number(row.dataset.planRow)],field=e.target.dataset.field;if(field==='time'||field==='endTime'){const a=row.querySelector('[data-field=time]').value,b=row.querySelector('[data-field=endTime]').value;s.time=a+(b?'–'+b:'');}else if(field)s[field]=field==='asNeeded'?e.target.checked:e.target.value;};
