      if(Object.keys(data.records).some(k=>k.split('|')[1]===date)){error.textContent='This day already has intake records. Choose another day to keep those records safe.';return;}
      if(occurrences(date).length&&!dialog.querySelector('#plan-replace').checked){error.textContent='Tick Replace the planned medicines to confirm the plan for this day.';return;}
      const next=JSON.parse(JSON.stringify(data));const now=new Date().toISOString();const list=draft.map(s=>({id:'day-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),name:s.name.trim(),dose:s.dose.trim(),times:[s.time],start:date,end:date,dayOnly:true,intakeDay:dialog.querySelector('#plan-intake-day').checked,asNeeded:!!s.asNeeded,instructions:s.instructions||'',createdAt:now}));next.schedules.push(...list);next.dayPlans=next.dayPlans||{};next.dayPlans[date]=list.map(s=>s.id);
