  function record(id,kind,actual,note){if(data.lockedDays?.[id.split('|')[1]]){status('This day is locked. Add a correction note in Saved history.');return;}const old=data.records[id];data.records[id]={status:kind,actual:kind==='taken'?actual:null,note,recordedAt:new Date().toISOString(),revisions:old?[...old.revisions,{status:old.status,actual:old.actual,note:old.note,recordedAt:old.recordedAt}]:[]};if(persist())status(t('saved'));renderRows();}
